import { useMemo, useState } from 'react';
import {
  JxCard,
  JxChip,
  JxChipGroup,
  JxStack,
  JxInline,
  JxText,
  JxBadge,
  JxCircularProgress,
  JxPagination,
  JxEmptyState,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded' | 'closed';

interface ProjectQuota {
  id: string;
  name: string;
  percent: number;
  status: ProjectStatus;
}

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'В рамках квоты',
  warning: 'Приближается к лимиту',
  exceeded: 'Квота превышена',
  closed: 'Проект закрыт',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'warning' | 'danger' | 'neutral'> = {
  active: 'success',
  warning: 'warning',
  exceeded: 'danger',
  closed: 'neutral',
};

const PROJECTS: ProjectQuota[] = [
  { id: 'p1', name: 'Атлас', percent: 42, status: 'active' },
  { id: 'p2', name: 'Борей', percent: 87, status: 'warning' },
  { id: 'p3', name: 'Вектор', percent: 108, status: 'exceeded' },
  { id: 'p4', name: 'Горизонт', percent: 15, status: 'active' },
  { id: 'p5', name: 'Дельта', percent: 100, status: 'closed' },
  { id: 'p6', name: 'Единорог', percent: 63, status: 'active' },
  { id: 'p7', name: 'Жасмин', percent: 91, status: 'warning' },
  { id: 'p8', name: 'Зенит', percent: 120, status: 'exceeded' },
  { id: 'p9', name: 'Икар', percent: 5, status: 'active' },
  { id: 'p10', name: 'Йота', percent: 100, status: 'closed' },
  { id: 'p11', name: 'Кристалл', percent: 76, status: 'warning' },
  { id: 'p12', name: 'Луна', percent: 33, status: 'active' },
];

const ALL_STATUSES: ProjectStatus[] = ['active', 'warning', 'exceeded', 'closed'];

const PAGE_SIZE = 5;

export default function ProjectQuotaSpendPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeFilters.includes(project.status)),
    [activeFilters]
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const pageProjects = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredProjects.slice(start, start + PAGE_SIZE);
  }, [filteredProjects, currentPage]);

  const toggleFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveFilters(ALL_STATUSES);
    setPage(1);
  };

  return (
    <JxCard className="jx-p-lg">
      <JxStack gap="lg">
        <JxStack gap="xs">
          <JxText variant="heading-sm">Расход по проектам</JxText>
          <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
            Фильтр по статусу квоты
          </JxText>
        </JxStack>

        <JxChipGroup>
          {ALL_STATUSES.map((status) => (
            <JxChip
              key={status}
              selected={activeFilters.includes(status)}
              tone={STATUS_TONES[status]}
              removable={activeFilters.includes(status)}
              onRemove={() => toggleFilter(status)}
              onClick={() => toggleFilter(status)}
            >
              {STATUS_LABELS[status]}
            </JxChip>
          ))}
        </JxChipGroup>

        <JxDivider />

        {filteredProjects.length === 0 ? (
          <JxEmptyState
            title="Нет проектов по выбранным фильтрам"
            description="Попробуйте сбросить фильтры, чтобы увидеть все проекты."
            action={
              <JxButton variant="secondary" onClick={resetFilters}>
                Сбросить фильтры
              </JxButton>
            }
          />
        ) : (
          <>
            <JxStack gap="sm">
              {pageProjects.map((project) => (
                <JxCard key={project.id} variant="outlined" className="jx-p-md">
                  <JxInline align="center" justify="space-between" gap="md">
                    <JxText variant="body-md" weight="medium">
                      {project.name}
                    </JxText>

                    <JxInline align="center" gap="md">
                      <JxCircularProgress
                        value={Math.min(project.percent, 100)}
                        size="sm"
                        tone={STATUS_TONES[project.status]}
                        label={`${project.percent}%`}
                      />
                      <JxBadge tone={STATUS_TONES[project.status]}>
                        {STATUS_LABELS[project.status]}
                      </JxBadge>
                    </JxInline>
                  </JxInline>
                </JxCard>
              ))}
            </JxStack>

            <JxPagination
              page={currentPage}
              pageCount={pageCount}
              onPageChange={setPage}
            />
          </>
        )}
      </JxStack>
    </JxCard>
  );
}

